```html
// Pendulum simulation

// Constants
const gravity = 9.81; // acceleration due to gravity in m/s^2
const angleInitial = 60; // initial angle in degrees
const timeStep = 0.01; // time step in seconds
const numSteps = 1000; // number of steps

// Variables
let angle = angleInitial * Math.PI / 180; // initial angle in radians
let velocity = 0; // initial velocity
let acceleration = gravity * Math.sin(angle); // initial acceleration
let currentStep = 0; // current step in the simulation
let displayHistory = []; // array to store the pendulum's position over time

// Button to release the pendulum
const releaseButton = document.getElementById("release-button");
releaseButton.addEventListener("click", releasePendulum);

// Draw the pendulum
function drawPendulum() {
  // Create a canvas element
  const canvas = document.getElementById("pendulum-canvas");
  if (!canvas) {
    canvas = document.createElement("canvas");
    canvas.id = "pendulum-canvas";
    document.body.appendChild(canvas);
  }
  const ctx = canvas.getContext("2d");

  // Clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Calculate the pendulum's position
  const radius = 100; // radius of the pendulum bob
  const x = radius * Math.sin(angle);
  const y = -radius * Math.cos(angle);

  // Draw the pendulum bob
  ctx.beginPath();
  ctx.arc(200 + x, 200 + y, radius, 0, 2 * Math.PI);
  ctx.fillStyle = "black";
  ctx.fill();

  // Draw the pendulum's path
  ctx.beginPath();
  ctx.moveTo(200, 200);
  ctx.lineTo(200 + x, 200 + y);
  ctx.stroke();

  // Display the pendulum's position over time
  displayHistory.push([x, y]);
  if (displayHistory.length > numSteps) {
    displayHistory.shift();
  }
  ctx.beginPath();
  for (let i = 0; i < displayHistory.length; i++) {
    const p1 = [200, 200];
    const p2 = [200 + displayHistory[i][0], 200 + displayHistory[i][1]];
    ctx.moveTo(p1[0], p1[1]);
    ctx.lineTo(p2[0], p2[1]);
  }
  ctx.stroke();
}

// Release the pendulum
function releasePendulum() {
  currentStep = 0;
  acceleration = gravity * Math.sin(angle);
  velocity = 0;
  angle = angleInitial * Math.PI / 180;
  displayHistory = [];
}

// Update the pendulum's position over time
function updatePendulum() {
  if (currentStep < numSteps) {
    acceleration = gravity * Math.sin(angle);
    velocity += acceleration * timeStep;
    angle += velocity * timeStep;
    currentStep++;
    if (!releaseButton.disabled) {
      setTimeout(updatePendulum, timeStep * 1000);
    }
  }
  drawPendulum();
}

// Start the simulation
updatePendulum();
